style.css:
/* 1. Fuerza el color celeste directo en la etiqueta nativa del botón */
button[type="submit"], 
[role="button"],
button {
    background-color: #1cc8f9 !important;
    background: #1cc8f9 !important;
}

/* 2. Color al pasar el cursor por encima */
button[type="submit"]:hover,
button:hover {
    background-color: #05b3e4 !important;
    background: #05b3e4 !important;
}
